Q: License Plate Factory A: <p>You have only one object, LicensePlateFactory, that keeps a counter for the next plate,
and delivers that plate.</p>
<p>So you need to create that factory only once, and use that object to get some new plate.</p>
<p>If you have concurrently running threads, could call <code>getNextPlate()</code> at the same time,
you need that the call to <code>getNextPlate()</code> is atomical.</p>
<p>Otherwise you risk giving the same plate number twice at rare times.</p>
<pre><code>// lastPlate == 100013             // lastPlate == 100013       
int plate = getNextPlate() {       int plate = getNextPlate() { 
    ++lastPlate;
                                       ++lastPlate;
    return lastPlate; // 100015
                                       return lastPlate; // 100015
}                                  }
</code></pre>
<p>The there are some solutions to prevent this.
Here I made the method <a href="https://docs.oracle.com/javase/tutorial/essential/concurrency/syncmeth.html" rel="nofollow noreferrer"><code>synchronized</code></a> ensuring that only one thread is allowed to execute the method, and other threads block during that time.</p>
<p>There is also <a href="https://docs.oracle.com/javase/8/docs/api/java/util/concurrent/atomic/AtomicInteger.html" rel="nofollow noreferrer"><code>AtomicInteger</code></a> as class, that holds an <code>int</code> and allows to atomically fetch that integer, at the same time increasing it.</p>
<p><code>AtomicInteger</code> would indeed be the nicer, more minimal solution, but needs more treatment in class, so I guess you have been tutored about synchronized.</p>
<pre><code>public class LicensePlateFactory 
{
    private static final int BEFORE_FIRST_PLATE = 100001;
    private int lastPlate = BEFORE_FIRST_PLATE;

    public LicensePlateFactory()
    {
    }

    public synchronized int getNextPlate()
    {   
        ++lastPlate;
        return lastPlate;   
    }
}

public class LicensePlateFactoryRunner 
{
    private LicensePlateFactory factory = new LicensePlateFactory();

    public LicensePlateFactoryRunner()
    {
        for (int x = 0; x &lt; 12; x++)
        {
            int plate = factory.getNextPlate();
            System.out.println(plate);
        }
    }
}
</code></pre>
<p><code>AtomicInteger</code> would use:</p>
<pre><code>    private AomicInteger lastPlate = new AtomicInteger(BEFORE_FIRST_PLATE);

        return lastPlate.incrementAndGet();
</code></pre>

Q: Long double not giving the required precision A: <p>To see the number in <code>C</code> in exponential notation (scientific) with 5 places after the decimal point use <code>&quot;%e&quot;</code>.</p>
<pre><code>fprintf(fp2,&quot;%.5Le\n&quot;,numberlist[j]);
fprintf(fp2,&quot;%.*Le\n&quot;, 5, numberlist[j]);
fprintf(fp2,&quot;%.Le\n&quot;,numberlist[j]);  // If not precision give, defaults to 6.
</code></pre>
<p>To see a FP value in <a href="https://stackoverflow.com/q/16839658/2410359">Printf width specifier to maintain precision</a> use</p>
<pre><code>#include &lt;float.h&gt;

fprintf(fp2,&quot;%.*Le\n&quot;, LDBL_DECIMAL_DIG - 1, numberlist[j]);
// or simply in hexadecimal notation
fprintf(fp2,&quot;%La\n&quot;, numberlist[j]);
</code></pre>

Q: Embed multiple view controllers in a container view A: <pre><code>import UIKit

class BaseViewController: UIViewController,
                          UITableViewDataSource,
                          UITableViewDelegate {

    /// Child VC will assign its tableView
    weak var managedTableView: UITableView?

    /// Override in child VC
    var cellIdentifier: String {
        fatalError(&quot;Override cellIdentifier in subclass&quot;)
    }

    override func viewDidLoad() {
        super.viewDidLoad()
    }
    @IBAction func btn1(_ sender: UIButton) {
        let vc = storyboard?.instantiateViewController(
               withIdentifier: &quot;ViewController1&quot;
           ) as! ViewController1

           navigationController?.pushViewController(vc, animated: true)
    }
    @IBAction func btn2(_ sender: UIButton) {
        let vc = storyboard?.instantiateViewController(
               withIdentifier: &quot;ViewController2&quot;
           ) as! ViewController2

           navigationController?.pushViewController(vc, animated: true)
    }

    /// Call this from child VC
    func configureTableView(_ tableView: UITableView) {
        managedTableView = tableView
        tableView.dataSource = self
        tableView.delegate = self
    }

    // MARK: - UITableViewDataSource

    func tableView(_ tableView: UITableView,
                   numberOfRowsInSection section: Int) -&gt; Int {
        return 5
    }

    func tableView(_ tableView: UITableView,
                   cellForRowAt indexPath: IndexPath) -&gt; UITableViewCell {

        let cell = tableView.dequeueReusableCell(
            withIdentifier: cellIdentifier,
            for: indexPath
        )

        // Common cell setup
        if let cell = cell as? MyCell1 {
            cell.vwCell?.backgroundColor = .red
        } else if let cell = cell as? MyCell2 {
            cell.vwCell.backgroundColor = .blue
        }

        return cell
    }
}




class ViewController1: BaseViewController {

    @IBOutlet weak var tableView1: UITableView!

    override var cellIdentifier: String {
        return &quot;MyCell1&quot;
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        configureTableView(tableView1)
    }
}

class ViewController2: BaseViewController {

    @IBOutlet weak var tableView2: UITableView!

    override var cellIdentifier: String {
        return &quot;MyCell2&quot;
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        configureTableView(tableView2)
    }
}


class MyCell1: UITableViewCell {
    @IBOutlet weak var vwCell: UIView?
}

class MyCell2: UITableViewCell {
    @IBOutlet weak var vwCell: UIView!
}
</code></pre>
